import torch
from torch.utils.cpp_extension import load_inline

# CUDA kernel implementation
cuda_source = """
#include <cuda_fp16.h>
#include <cmath>

__device__ __forceinline__ half gelu_kernel(half x) {
    // GELU(x) = x * Φ(x) where Φ is the CDF of the standard normal distribution
    // Using approximation: GELU(x) ≈ 0.5 * x * (1 + tanh(√(2/π) * (x + 0.044715 * x^3)))
    const float kAlpha = 0.5f;
    const float kBeta = 0.7978845608028654f; // sqrt(2/pi)
    const float kGamma = 0.044715f;

    float xf = __half2float(x);
    float result = kAlpha * xf * (1.0f + tanhf(kBeta * (xf + kGamma * xf * xf * xf)));
    return __float2half(result);
}

__global__ void gelu_kernel_forward(const half* input, half* output, int64_t total_elements) {
    int64_t idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < total_elements) {
        output[idx] = gelu_kernel(input[idx]);
    }
}

extern "C" {
    void gelu_forward_cuda(const half* input, half* output, int64_t total_elements) {
        const int block_size = 256;
        const int grid_size = (total_elements + block_size - 1) / block_size;
        gelu_kernel_forward<<<grid_size, block_size>>>(input, output, total_elements);
    }
}
"""

# Load the CUDA extension
